multisyntax.syntax-highlight:
#include "ntgcalls.h"

int main() {
    ntg_instance* handle = ntg_instance_create();

    char* out = NULL;
    ntg_ping(&out);
    ntg_instance_destroy(handle);
    return 0;
}

const { NTgCalls } = require('ntgcalls');

const app = new NTgCalls();
console.log(await NTgCalls.ping());

import io.github.pytgcalls.NTgCalls;

NTgCalls app = new NTgCalls();
System.out.println(NTgCalls.ping());

use ntgcalls::NTgCalls;

let app = NTgCalls::new();
println!("{}", NTgCalls::ping()?);

lang-block.syntax-highlight:
void on_log(ntg_log_message message, void* user_data) {
    printf("%s:%u %s\n", message.file, message.line, message.message);
}

int main() {
    ntg_set_log_callback(&on_log, NULL);
    ...
}
